# 4. Concurrency / Thread-Safety
# ---------------------------------------------------------------------------

class TestConcurrency:
    """Verify thread-safety and concurrent access patterns."""

    def test_concurrent_generate_calls(self, mock_llm_client):
        """Multiple threads must safely call generate simultaneously."""
        errors: List[Exception] = []
        results: List[Dict[str, str]] = []

        def worker(prompt: str):
            try:
                result = mock_llm_client.generate(prompt)
                results.append(result)
            except Exception as e:  # pragma: no cover
                errors.append(e)

        with ThreadPoolExecutor(max_workers=CONCURRENCY_LEVEL) as executor:
            futures = [
                executor.submit(worker, f"prompt_{i}")
                for i in range(CONCURRENCY_ITERATIONS)
            ]
            for future in as_completed(futures):
                future.result()  # Propagate exceptions

        assert not errors, f"Concurrent execution failed: {errors}"
        assert len(results) == CONCURRENCY_ITERATIONS

    def test_thread_safety_stateful_client(self, stateful_llm_client):
        """Stateful client must maintain correct call count under concurrency."""
        with ThreadPoolExecutor(max_workers=8) as executor:
            futures = [
                executor.submit(stateful_llm_client.generate, f"prompt_{i}")
                for i in range(50)
            ]
            for future in as_completed(futures):
                future.result()

        assert stateful_llm_client.call_count["n"] == 50

    def test_no_shared_state_corruption(self, mock_llm_client):
        """Concurrent calls must not corrupt shared state."""
        results: List[Dict[str, str]] = []
        lock = threading.Lock()

        def worker(prompt: str):
            result = mock_llm_client.generate(prompt)
            with lock:
                results.append(result)

        threads = [
            threading.Thread(target=worker, args=(f"prompt_{i}",))
            for i in range(20)
        ]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert len(results) == 20
        # All results should be identical (deterministic mock)
        assert all(r == results[0] for r in results)

    def test_concurrent_exception_isolation(self, failing_llm_client):
        """Exceptions in one thread must not affect others."""
        healthy_client = MagicMock()
        healthy_client.generate.return_value = {"text": "ok"}

        def failing_worker():
            with pytest.raises(RuntimeError):
                failing_llm_client.generate("prompt")

        def healthy_worker():
            result = healthy_client.generate("prompt")
            assert result["text"] == "ok"

        with ThreadPoolExecutor(max_workers=4) as executor:
            f1 = executor.submit(failing_worker)
            f2 = executor.submit(healthy_worker)
            f3 = executor.submit(healthy_worker)
            f4 = executor.submit(failing_worker)

            for f in [f1, f2, f3, f4]:
                f.result()  # Should not raise


