class TestPerformanceRegression:
    """Verify latency bounds and performance characteristics."""

    def test_generate_latency_within_bounds(self, slow_llm_client):
        """Client must complete within latency budget."""
        start = time.perf_counter()
        slow_llm_client.generate("prompt", delay_ms=10)
        elapsed_ms = (time.perf_counter() - start) * 1000

        assert elapsed_ms < MAX_LATENCY_MS, (
            f"Latency {elapsed_ms:.2f}ms exceeds bound {MAX_LATENCY_MS}ms"
        )

    def test_generate_latency_linear_scaling(self, slow_llm_client):
        """Latency should scale linearly with delay parameter."""
        delays = [5, 10, 20]
        latencies = []

        for delay in delays:
            start = time.perf_counter()
            slow_llm_client.generate("prompt", delay_ms=delay)
            latencies.append((time.perf_counter() - start) * 1000)

        # Verify monotonic increase
        assert latencies[0] < latencies[1] < latencies[2]

    def test_throughput_under_load(self, mock_llm_client):
        """Client must handle sustained load without degradation."""
        start = time.perf_counter()
        for i in range(100):
            mock_llm_client.generate(f"prompt_{i}")
        total_ms = (time.perf_counter() - start) * 1000

        # 100 calls should complete quickly with mock
        assert total_ms < 1000, f"100 calls took {total_ms:.2f}ms"

    def test_memory_stability(self, mock_llm_client):
        """Repeated calls should not cause memory growth (mock-level)."""
        import tracemalloc

        tracemalloc.start()
        for i in range(50):
            mock_llm_client.generate(f"prompt_{i}")
        current, peak = tracemalloc.get_traced_memory()
        tracemalloc.stop()

        # Peak memory should be bounded for mock operations
        assert peak < 10 * 1024 * 1024, f"Peak memory {peak} exceeds 10MB"


